1	import java.util.Comparator;
2	import java.util.NoSuchElementException;
3	
4	class MinHeapTest {
5	
6	    interface ThrowingRunnable {
7	        void run() throws Exception;
8	    }
9	
10	    private static int passed = 0;
11	    private static int failed = 0;
12	
13	    public static void main(String[] args) {
14	        testInsertAndExtract();
15	        testDeleteKey();
16	        testDecreaseKey();
17	        testIncreaseKey();
18	        testChangeKey();
19	        testAutoResize();
20	        testEmptyHeap();
21	        testFromArray();
22	        testWithStrings();
23	        testMaxHeap();
24	        testCustomComparator();
25	        testToString();
26	        testToArray();
27	        testToSortedArray();
28	        testSort();
29	        testOriginalScenario();
30	
31	        System.out.println("\n" + passed + " passed, " + failed + " failed.");
32	        if (failed > 0) System.exit(1);
33	    }
34	
35	    private static void assertEqual(Object expected, Object actual, String msg) {
36	        if (expected.equals(actual)) {
37	            System.out.println("PASS: " + msg);
38	            passed++;
39	        } else {
40	            System.out.println("FAIL: " + msg + " (expected=" + expected + ", got=" + actual + ")");
41	            failed++;
42	        }
43	    }
44	
45	    private static void assertTrue(boolean condition, String msg) {
46	        if (condition) {
47	            System.out.println("PASS: " + msg);
48	            passed++;
49	        } else {
50	            System.out.println("FAIL: " + msg);
51	            failed++;
52	        }
53	    }
54	
55	    private static void assertThrows(ThrowingRunnable r, Class<? extends Exception> exClass, String msg) {
56	        try {
57	            r.run();
58	            System.out.println("FAIL: " + msg + " (no exception thrown)");
59	            failed++;
60	        } catch (Exception e) {
61	            if (exClass.isInstance(e)) {
62	                System.out.println("PASS: " + msg);
63	                passed++;
64	            } else {
65	                System.out.println("FAIL: " + msg + " (wrong exception: " + e.getClass().getSimpleName() + ")");
66	                failed++;
67	            }
68	        }
69	    }
70	
71	    private static void testInsertAndExtract() {
72	        MinHeap<Integer> h = MinHeap.naturalOrder();
73	        h.insertKey(5);
74	        h.insertKey(3);
75	        h.insertKey(8);
76	        h.insertKey(1);
77	        assertEqual(1, h.extractMin(), "extractMin returns smallest");
78	        assertEqual(3, h.extractMin(), "extractMin returns next smallest");
79	        assertEqual(5, h.extractMin(), "extractMin returns next");
80	        assertEqual(8, h.extractMin(), "extractMin returns last");
81	        assertTrue(h.isEmpty(), "heap is empty after all extractions");
82	    }
83	
84	    private static void testDeleteKey() {
85	        MinHeap<Integer> h = MinHeap.naturalOrder(11);
86	        h.insertKey(3);
87	        h.insertKey(2);
88	        h.deleteKey(1);
89	        h.insertKey(15);
90	        h.insertKey(5);
91	        h.insertKey(4);
92	        h.insertKey(45);
93	        assertEqual(2, h.extractMin(), "extractMin after deleteKey");
94	        assertEqual(4, h.getMin(), "getMin after extract");
95	
96	        MinHeap<Integer> h2 = MinHeap.naturalOrder();
97	        h2.insertKey(1);
98	        h2.insertKey(3);
99	        h2.insertKey(5);
100	        h2.deleteKey(2);
101	        assertEqual(2, h2.size(), "size after deleting last element");
102	        assertEqual(1, h2.extractMin(), "min unchanged after deleting last");
103	
104	        MinHeap<Integer> h3 = MinHeap.naturalOrder();
105	        h3.insertKey(1);
106	        h3.insertKey(3);
107	        h3.insertKey(5);
108	        h3.deleteKey(0);
109	        assertEqual(3, h3.extractMin(), "new root after deleting old root");
110	    }
111	
112	    private static void testDecreaseKey() {
113	        MinHeap<Integer> h = MinHeap.naturalOrder();
114	        h.insertKey(10);
115	        h.insertKey(20);
116	        h.insertKey(30);
117	        h.decreaseKey(2, 5);
118	        assertEqual(5, h.extractMin(), "decreaseKey moves element up correctly");
119	    }
120	
121	    private static void testIncreaseKey() {
122	        MinHeap<Integer> h = MinHeap.naturalOrder();
123	        h.insertKey(1);
124	        h.insertKey(5);
125	        h.insertKey(10);
126	        h.increaseKey(0, 15);
127	        assertEqual(5, h.extractMin(), "increaseKey on root restores heap property");
128	    }
129	
130	    private static void testChangeKey() {
131	        MinHeap<Integer> h = MinHeap.naturalOrder();
132	        h.insertKey(5);
133	        h.insertKey(10);
134	        h.changeKey(1, 1);
135	        assertEqual(1, h.extractMin(), "changeKey decrease works");
136	
137	        MinHeap<Integer> h2 = MinHeap.naturalOrder();
138	        h2.insertKey(3);
139	        h2.insertKey(8);
140	        h2.changeKey(0, 20);
141	        assertEqual(8, h2.extractMin(), "changeKey increase works");
142	
143	        MinHeap<Integer> h3 = MinHeap.naturalOrder();
144	        h3.insertKey(7);
145	        h3.changeKey(0, 7);
146	        assertEqual(7, h3.getMin(), "changeKey no-op when value unchanged");
147	    }
148	
149	    private static void testAutoResize() {
150	        MinHeap<Integer> h = MinHeap.naturalOrder(2);
151	        for (int i = 10; i >= 1; i--) {
152	            h.insertKey(i);
153	        }
154	        assertEqual(10, h.size(), "auto-resize: correct size after growing beyond initial capacity");
155	        assertEqual(1, h.extractMin(), "auto-resize: extracts minimum correctly");
156	        assertEqual(2, h.extractMin(), "auto-resize: maintains order after resize");
157	    }
158	
159	    private static void testEmptyHeap() {
160	        MinHeap<Integer> h = MinHeap.naturalOrder();
161	        assertTrue(h.isEmpty(), "new heap is empty");
162	        assertEqual(0, h.size(), "new heap has size 0");
163	        assertThrows(() -> h.extractMin(), NoSuchElementException.class, "extractMin on empty throws");
164	        assertThrows(() -> h.getMin(), NoSuchElementException.class, "getMin on empty throws");
165	    }
166	
167	    private static void testFromArray() {
168	        Integer[] arr = {5, 3, 8, 1, 9, 2};
169	
170	        MinHeap<Integer> h = MinHeap.from(arr);
171	        assertEqual(6, h.size(), "from: correct size");
172	        assertEqual(1, h.extractMin(), "from: extracts minimum");
173	        assertEqual(2, h.extractMin(), "from: extracts next");
174	        assertEqual(3, h.extractMin(), "from: extracts in sorted order");
175	
176	        Integer[] single = {42};
177	        MinHeap<Integer> h2 = MinHeap.from(single);
178	        assertEqual(42, h2.extractMin(), "from single-element array");
179	        assertTrue(h2.isEmpty(), "empty after extracting sole element");
180	
181	        MinHeap<Integer> h3 = MinHeap.from(arr, Comparator.reverseOrder());
182	        assertEqual(9, h3.extractMin(), "from with reverse comparator extracts maximum");
183	    }
184	
185	    private static void testWithStrings() {
186	        MinHeap<String> h = MinHeap.naturalOrder();
187	        h.insertKey("banana");
188	        h.insertKey("apple");
189	        h.insertKey("cherry");
190	        assertEqual("apple", h.extractMin(), "string heap extracts lexicographic minimum");
191	        assertEqual("banana", h.extractMin(), "string heap extracts next");
192	    }
193	
194	    private static void testMaxHeap() {
195	        MinHeap<Integer> h = MinHeap.reverseOrder();
196	        h.insertKey(5);
197	        h.insertKey(3);
198	        h.insertKey(8);
199	        h.insertKey(1);
200	        assertEqual(8, h.extractMin(), "max-heap: extracts largest first");
201	        assertEqual(5, h.extractMin(), "max-heap: extracts next largest");
202	    }
203	
204	    private static void testCustomComparator() {
205	        MinHeap<String> byLength = MinHeap.withComparator(Comparator.comparingInt(String::length));
206	        byLength.insertKey("banana");
207	        byLength.insertKey("fig");
208	        byLength.insertKey("kiwi");
209	        assertEqual("fig", byLength.extractMin(), "custom comparator: shortest string first");
210	        assertEqual("kiwi", byLength.extractMin(), "custom comparator: next shortest");
211	    }
212	
213	    private static void testToString() {
214	        MinHeap<Integer> h = MinHeap.naturalOrder();
215	        assertEqual("[]", h.toString(), "toString on empty heap");
216	        h.insertKey(3);
217	        h.insertKey(1);
218	        h.insertKey(2);
219	        assertTrue(h.toString().startsWith("[1"), "toString: root is minimum");
220	        assertTrue(h.toString().contains("2"), "toString: contains 2");
221	        assertTrue(h.toString().contains("3"), "toString: contains 3");
222	    }
223	
224	    private static void testToArray() {
225	        MinHeap<Integer> h = MinHeap.naturalOrder();
226	        assertEqual(0, h.toArray().length, "toArray on empty heap");
227	
228	        h.insertKey(3);
229	        h.insertKey(1);
230	        h.insertKey(2);
231	        Object[] arr = h.toArray();
232	        assertEqual(3, arr.length, "toArray: correct length");
233	        assertEqual(1, arr[0], "toArray: root is minimum");
234	        // Non-root order is heap-dependent; verify all values present via sum.
235	        int sum = (Integer) arr[0] + (Integer) arr[1] + (Integer) arr[2];
236	        assertEqual(6, sum, "toArray: all elements present");
237	        assertEqual(3, h.size(), "toArray is non-destructive");
238	    }
239	
240	    private static void testToSortedArray() {
241	        Integer[] input = {5, 3, 8, 1, 9, 2};
242	        MinHeap<Integer> h = MinHeap.from(input);
243	        Object[] sorted = h.toSortedArray();
244	
245	        assertEqual(6, sorted.length, "toSortedArray: correct length");
246	        Integer[] expected = {1, 2, 3, 5, 8, 9};
247	        for (int i = 0; i < expected.length; i++) {
248	            assertEqual(expected[i], sorted[i], "toSortedArray: element at index " + i);
249	        }
250	        assertEqual(6, h.size(), "toSortedArray: non-destructive");
251	
252	        // With reverse comparator — sorted descending.
253	        MinHeap<Integer> maxH = MinHeap.from(input, Comparator.reverseOrder());
